package workbench

func addEditHistoryDetails(id string, schema map[string]any) bool {
	if id != "edit.batch" && id != "edit.undo" && id != "edit.redo" {
		return false
	}
	c := commandContractDetail{Version: 1, Scope: "atomic-edits-and-history", Preconditions: []string{"Common protocol/revision/document/actor/retry guards apply before the command; one outer mutation guard and key cover the entire operation"}, Effects: []string{"Successful admission advances command revision even for unchanged final content. Successful retries return independently owned original snapshots before new guard checks, not a fresh snapshot or another edit", "Saved-file association/baselines and kept captured assets are independent of schematic history. Dirty flags compare current contents with the latest saved baseline, not the existence of an undo entry"}, Errors: []commandFailureDetail{{"invalid-params", "admission", "Malformed/unknown/duplicate fields or command-specific domain validation"}}, Completion: &commandCompletionDetail{Mode: "immediate schematic/history commit; electrical edits use existing startup/paused stale rules", Observe: []string{"project.inspect", "simulation.wait", "events.poll"}}}
	if id == "edit.batch" {
		p := inputProperty(schema, "name")
		p["minLength"], p["maxLength"], p["x-max-utf8-bytes"] = 1, 80, 80
		p["description"] = "Required non-null name, not all whitespace, 1–80 UTF-8 bytes including surrounding whitespace. Stored verbatim if final document content adds an undo entry."
		p = inputProperty(schema, "edits")
		p["minItems"], p["maxItems"] = 1, 100
		item := p["items"].(map[string]any)
		item["required"] = []string{"command", "params"}
		inputProperty(item, "command")["enum"] = append([]string{}, atomicBatchCommands[:]...)
		inputProperty(item, "params")["description"] = "Required non-null object in this edit command's parameter grammar; query capabilities.list {command: EDIT_COMMAND} for bounds, quantities and fields. Child commands carry no separate protocol envelope/key/revision. Batch staging overrides live actuation/completion semantics."
		schema["x-supported-edit-commands"] = append([]string{}, atomicBatchCommands[:]...)
		c.Preconditions = append(c.Preconditions, "Required non-null name and 1–100 edits; each edit needs a nonempty allowed command and parameter object. No nested batches, file work, queries, run controls, history, pin/display preferences or general experiment-settings command", "Edits validate in order against cloned graph/settings/drawing/selection/lifetime IDs. Later edits can use earlier explicit IDs, wiring and staged values; each intermediate edit must be structurally valid, but the circuit need not be electrically complete")
		c.Effects = append(c.Effects, "Any rejected child discards all staged graph/settings/drawing/selection and ID reservations; preserves public state, history, physical readings/run/time and files. Error messages identify the 1-based edit index when child execution fails", "Commits staged graph/transient settings/selection/drawing/ID reservations once. A final graph/settings change adds one named actor/revision-attributed undo entry, clears redo and follows ordinary electrical versus geometry-only edit behavior", "A batch with unchanged final graph/settings adds no history entry and preserves redo/accepted physics. It can still consume lifetime IDs for components/wires created then deleted, change editing selection/drawing and advance the outer command revision", "Switch/wiper edits are staged startup configuration, not live queued actuation. Sampling Fit uses preceding staged values. Finite and ideal-square timing bounds use staged experiment settings. All selected children reuse their ordinary value/geometry/quantity validation", "Undo restores graph/settings/pins/display/example contents only; it does not release IDs from a successful batch or restore editing selection/drawing, file association, kept data or live time/charge")
		schema["examples"] = []any{map[string]any{"name": "Tune RC pair", "edits": []any{map[string]any{"command": "component.set", "params": map[string]any{"id": "R1", "value": "20k"}}, map[string]any{"command": "component.set", "params": map[string]any{"id": "C1", "value": "2uF"}}}}}
	} else {
		schema["x-history-inventory"] = "snapshot.undo_entry or redo_entry: name, original actor and original command_revision. The entry revision is not snapshot.command_revision. Entries retain identity through undo/redo."
		schema["x-max-undo-entries"] = 100
		inputProperty(schema, "expected_entry_revision")["description"] = "Optional omitted/null adds no exact-tip guard; supplied uint64 must equal the chosen undo_entry/redo_entry.command_revision. Zero is an actual comparison, not a disable sentinel."
		inputProperty(schema, "allow_other_actor")["description"] = "Optional omitted/null/false refuses a tip owned by another actor. True acknowledges another actor only after any exact-tip guard matches; it does not bypass context guards."
		c.Preconditions = append(c.Preconditions, "After common guards and parameter decoding: requested stack nonempty, optional exact tip revision matches, then original tip actor equals caller or allow_other_actor=true")
		c.Errors = append(c.Errors, commandFailureDetail{"unavailable", "admission", "No entry on the requested stack"}, commandFailureDetail{"history-conflict", "admission", "Exact tip revision differs, or another actor owns the tip without acknowledgment"})
		c.Effects = append(c.Effects, "Restores one graph/transient-settings/pinned/display/example history state and moves the counterpart to the opposite stack under the original name/actor/entry revision, even when another actor explicitly acknowledges it", "History is session-local and bounded, not loaded from project/recovery files. A later changed document edit clears redo; presentation-only session controls and accepted final-content no-op batches do not necessarily clear it", "Preserves file association/baselines, document generation, kept recordings/sweeps/viewer membership, viewport/pause and lifetime ID reservations. Undoing New/Open does not reassociate an older saved path or resurrect removed captured assets", "Does not rewind numerical time/charge or jobs. Cancels pending input work; electrical/settings differences advance requested run/electrical revision and follow paused stale/restart rules, while geometry/presentation differences preserve accepted physics. Drawing references/selection may normalize when restored objects differ", "Admitted history actions may affect eligibility of pending captured file/analysis work through their usual current-source guards; they do not roll back a publishing file or an external artifact")
	}
	schema["x-command-contract"] = c
	return true
}
